            ret->headers = (struct http_headers *)calloc(1, sizeof(struct http_headers));
            ret->headers->uri_headers = kv;
          }
        }

        const char *path = evhttp_uri_get_path(uri);
        if (path && ret) {
          ret->path = strdup(path);
        }

        evhttp_uri_free(uri);

        if (parse_post && ret) {
          char *body = strstr(s + 1, "\r\n\r\n");
